    if raw is None:
        return {}
    if isinstance(raw, str):
        # Try parsing as JSON or eval-style list
        try:
            raw = json.loads(raw)
        except (json.JSONDecodeError, ValueError):
            return {}
    if hasattr(raw, "tolist"):
