class ChainStateManager:
    """Read/write vllm_manager_state.json with file locking."""

    def __init__(self, project_root: Path):
        self.state_dir = project_root / "spatial_agent" / "logs"
        self.state_dir.mkdir(parents=True, exist_ok=True)
        self.state_file = self.state_dir / "vllm_manager_state.json"
        self.lock_file = str(self.state_file) + ".lock"

    def _read(self) -> List[dict]:
        if not self.state_file.exists():
            return []
        try:
            with open(self.state_file, "r") as f:
                return json.load(f)
        except (json.JSONDecodeError, FileNotFoundError):
            return []

    def _write(self, chains: List[dict]) -> None:
        with open(self.state_file, "w") as f:
            json.dump(chains, f, indent=2)

    def add_chain(self, chain: ChainState) -> None:
        with FileLock(self.lock_file):
            chains = self._read()
            chains.append(asdict(chain))
            self._write(chains)

    def remove_chain(self, chain_id: str) -> None:
        with FileLock(self.lock_file):
            chains = self._read()
            chains = [c for c in chains if c.get("chain_id") != chain_id]
            self._write(chains)

    def update_chain_jobs(self, chain_id: str, slurm_job_ids: List[str]) -> None:
        with FileLock(self.lock_file):
            chains = self._read()
            for c in chains:
                if c.get("chain_id") == chain_id:
                    c["slurm_job_ids"] = slurm_job_ids
                    break
            self._write(chains)

    def list_chains(self) -> List[ChainState]:
        with FileLock(self.lock_file):
            raw = self._read()
        result = []
        for c in raw:
            try:
                result.append(ChainState(**c))
            except TypeError:
                continue
        return result

    def is_chain_alive(self, chain: ChainState) -> bool:
        """Check if the manager process PID is still running."""
        try:
            os.kill(chain.pid, 0)
            return True
        except (ProcessLookupError, PermissionError):
            return False

    def cleanup_dead_chains(self) -> List[ChainState]:
        """Remove chains whose manager PID is dead. Returns removed chains."""
        with FileLock(self.lock_file):
            chains = self._read()
            alive = []
            dead = []
            for c in chains:
                pid = c.get("pid", 0)
                try:
                    os.kill(pid, 0)
                    alive.append(c)
                except (ProcessLookupError, PermissionError, OSError):
                    dead.append(c)
            self._write(alive)
        return [ChainState(**c) for c in dead if _is_valid_chain(c)]


def _is_valid_chain(c: dict) -> bool:
    try:
        ChainState(**c)
        return True
    except TypeError:
        return False

"""Drawing utilities for image annotation."""

from typing import List, Optional, Sequence, Tuple, Union

import cv2
import matplotlib.colors as mcolors
import numpy as np
from PIL import Image

from spatial_agent.tools.base import CPUTool

Color = Union[Tuple[int, int, int], str]


def _resolve_color(color: Color) -> Tuple[int, int, int]:
    """Convert a color name or RGB tuple to an (R, G, B) uint8 tuple.

    Named colors are resolved via matplotlib (CSS4 + base colors).
    """
    if isinstance(color, str):
        try:
            rgba = mcolors.to_rgba(color)
        except ValueError:
            raise ValueError(
                f"Unknown color name '{color}'. "
                f"Use any matplotlib/CSS4 color name (e.g. 'red', 'dodgerblue', 'salmon') "
                f"or an (R, G, B) tuple."
            )
        return (int(round(rgba[0] * 255)), int(round(rgba[1] * 255)), int(round(rgba[2] * 255)))
    if isinstance(color, (tuple, list)) and len(color) == 3:
        return (int(color[0]), int(color[1]), int(color[2]))
    raise ValueError(
        f"Color must be an (R, G, B) tuple or a name string, got {color!r}"
    )


def _to_numpy(image) -> np.ndarray:
    """Convert image to (H, W, 3) uint8 numpy array.

    Accepts numpy array, PIL Image, or FrameImage (InputImages[i]).
    """
    # FrameImage delegates .convert() to its inner PIL Image via __getattr__
    if hasattr(image, "convert") and callable(image.convert):
        return np.array(image.convert("RGB"))
    if isinstance(image, np.ndarray):
        if image.ndim != 3 or image.shape[2] != 3:
            raise ValueError(
                f"`image` must be (H, W, 3), got shape {image.shape}."
            )
        return image
    raise TypeError(
        f"`image` must be a numpy array, PIL Image, or InputImages[i], "
        f"got {type(image).__name__}."
    )


def _is_single_coord(seq) -> bool:
    """True if seq looks like a single coordinate tuple (all elements are numbers)."""
    if isinstance(seq, np.ndarray):
        return seq.ndim == 1
    return len(seq) > 0 and isinstance(seq[0], (int, float, np.integer, np.floating))


def _broadcast_colors(
    colors: Optional[Union[Color, List[Color]]],
    n: int,
    default: Tuple[int, int, int],
) -> List[Tuple[int, int, int]]:
    """Broadcast colors to length n."""
    if colors is None:
        return [default] * n
    # Single color (string or tuple)
    if isinstance(colors, str):
        return [_resolve_color(colors)] * n
    if isinstance(colors, (tuple, list)):
        # Check if it's a single RGB tuple (3 ints) vs. a list of colors
        if len(colors) == 3 and isinstance(colors[0], (int, float, np.integer, np.floating)):
            return [_resolve_color(colors)] * n
        # List of colors
        resolved = [_resolve_color(c) for c in colors]
        if len(resolved) != n:
            raise ValueError(
                f"Got {len(resolved)} colors but {n} primitives. "
                f"Provide one color for all, or one per primitive."
            )
        return resolved
    return [_resolve_color(colors)] * n


